import { museumRequest } from './request';
export const galleryResource = {
  list(room: string) {
    return museumRequest({ path: '/works', query: new URLSearchParams({ room }) });
  },
  annotate(workKey: string, note: string, curator: string) {
    return museumRequest({ path: `/works/${encodeURIComponent(workKey)}/annotations`, method: 'POST', headers: { 'X-Curator': curator }, body: JSON.stringify({ note }) });
  },
};
