interface MuseumRequest { path: string; method?: string; query?: URLSearchParams; body?: BodyInit; headers?: Record<string, string>; }
const museumRoot = '/museum/v4';
const sharedHeaders = { 'X-Gallery-Lesson': 'object-resource' };
export function museumRequest(contract: MuseumRequest) {
  const query = contract.query ? `?${contract.query}` : '';
  return fetch(`${museumRoot}${contract.path}${query}`, { ...contract, method: contract.method ?? 'GET', headers: { ...sharedHeaders, ...contract.headers } });
}
